contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint val) public payable {
        bool revertedOnce;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedOnce = true;
        } else {
            revertedOnce = false;
        }
        uint got = c.MinSum(); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertedTwice;
        c.SetMinSum(val); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedTwice = true;
        } else {
            revertedTwice = false;
        }

        assert(revertedTwice && c.MinSum() == got);
    }

    receive() external payable {}
}

