pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 val) internal {
        bool revertedOnce;
        try c.SetMinSum(val) {
            revertedOnce = false;
        } catch {
            revertedOnce = true;
        }
        uint256 got;
        try c.MinSum() returns (uint256 __r) { got = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        bool revertedTwice;
        try c.SetMinSum(val) {
            revertedTwice = false;
        } catch {
            revertedTwice = true;
        }
        assertTrue(revertedTwice && c.MinSum() == got);
    }

    function testFuzz_run(uint256 val) public {
        _run(val);
    }

    receive() external payable {}
}
